/// <summary>
/// PricingAttribute of table <c>DirPartyTable</c> field KnownAs.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeDirPartyTableKnownAs extends GUPPricingAttributeDirPartyTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(DirPartyTable, KnownAs);
}

public Set getAllowedValues()
{
    var           ret = new Set(Types::String);
    DirPartyTable dirPartyTable;

    while select dirPartyTable
        group by KnownAs
    {
        if (! ret.in(dirPartyTable.KnownAs))
        {
            ret.add(dirPartyTable.KnownAs);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(DirPartyTable, KnownAs));
    qbr.value(queryValue(_value));
}
